scan_linter_check.script:
(function(engine) {
    global.EcsGlideRecord.runBulkCheck(engine, {
        ruleId: 'SN-GR-002-R',
        tier: 'review',
        bulkMethod: 'deleteMultiple',
        perRecordMethod: 'deleteRecord',
        title: 'GlideRecord delete whose query conditions could not be verified',
        recommendation: 'Confirm the conditions always restrict the delete: validate run-time values (empty or ' +
            'undefined values and invalid field names may widen the query), avoid adding conditions on only some ' +
            'code paths, and check the affected count before deleting. Mute this finding with a reason once reviewed.'
    });
})(engine);
